package com.agentclientprotocol.client

import com.agentclientprotocol.client.v2.Client
import com.agentclientprotocol.client.v2.ClientInfo
import com.agentclientprotocol.model.AuthMethodId
import com.agentclientprotocol.model.Implementation
import com.agentclientprotocol.model.PROTOCOL_VERSION_V2
import com.agentclientprotocol.protocol.AcpExpectedError
import com.agentclientprotocol.protocol.Protocol
import com.agentclientprotocol.rpc.ACPJson
import com.agentclientprotocol.rpc.JsonRpcError
import com.agentclientprotocol.rpc.JsonRpcErrorCode
import com.agentclientprotocol.rpc.JsonRpcErrorResponse
import com.agentclientprotocol.rpc.JsonRpcMessage
import com.agentclientprotocol.rpc.JsonRpcRequest
import com.agentclientprotocol.rpc.JsonRpcResponse
import com.agentclientprotocol.rpc.JsonRpcSuccessResponse
import com.agentclientprotocol.rpc.TransportFrame
import com.agentclientprotocol.transport.BaseTransport
import com.agentclientprotocol.transport.Transport
import kotlinx.coroutines.runBlocking
import kotlinx.coroutines.withTimeout
import kotlinx.serialization.json.JsonElement
import kotlin.test.Test
import kotlin.test.assertEquals
import kotlin.test.assertFailsWith
import kotlin.test.assertTrue
import kotlin.time.Duration.Companion.seconds

class V2ClientAuthenticationTest {
    @Test
    fun `omitted auth methods prevent login and logout requests`() = withClient(
        """{
            "protocolVersion":2,
            "info":{"name":"agent","version":"1"},
            "capabilities":{"auth":{}}
        }""",
    ) { client, transport ->
        assertAuthenticationUnavailable(client, transport)
    }

    @Test
    fun `empty auth methods prevent login and logout requests`() = withClient(
        """{
            "protocolVersion":2,
            "info":{"name":"agent","version":"1"},
            "capabilities":{"auth":{}},
            "authMethods":[]
        }""",
    ) { client, transport ->
        assertAuthenticationUnavailable(client, transport)
    }

    @Test
    fun `authentication before initialization fails locally`() = withClient(
        AUTHENTICATED_AGENT,
        initialize = false,
    ) { client, transport ->
        val loginFailure = assertFailsWith<AcpExpectedError> { client.login(AuthMethodId("oauth")) }
        assertTrue(loginFailure.message.contains("initialization"))
        assertTrue(transport.sent.isEmpty())

        val logoutFailure = assertFailsWith<AcpExpectedError> { client.logout() }
        assertTrue(logoutFailure.message.contains("initialization"))
        assertTrue(transport.sent.isEmpty())
    }

    @Test
    fun `advertised authentication uses v2 method names and preserves metadata`() = withClient(
        AUTHENTICATED_AGENT,
    ) { client, transport ->
        val requestMeta = ACPJson.parseToJsonElement("""{"trace":"auth-test"}""")
        val responseMeta = ACPJson.parseToJsonElement("""{"source":"agent"}""")

        assertEquals(responseMeta, client.login(AuthMethodId("oauth"), requestMeta)._meta)
        assertEquals(responseMeta, client.logout(requestMeta)._meta)

        val requests = transport.sent.filterIsInstance<JsonRpcRequest>()
        assertEquals(listOf("initialize", "auth/login", "auth/logout"), requests.map { it.method.name })
        assertEquals(
            ACPJson.parseToJsonElement("""{"methodId":"oauth","_meta":{"trace":"auth-test"}}"""),
            requests[1].params,
        )
        assertEquals(
            ACPJson.parseToJsonElement("""{"_meta":{"trace":"auth-test"}}"""),
            requests[2].params,
        )
    }

    @Test
    fun `a methodId outside the advertised list prevents the login request`() = withClient(
        AUTHENTICATED_AGENT,
    ) { client, transport ->
        val sentBefore = transport.sent.toList()

        val failure = assertFailsWith<AcpExpectedError> { client.login(AuthMethodId("api-key")) }
        assertTrue(failure.message.contains("auth/login"), "unexpected failure: ${failure.message}")
        assertTrue(failure.message.contains("api-key"), "unexpected failure: ${failure.message}")
        assertTrue(failure.message.contains("oauth"), "unexpected failure: ${failure.message}")
        assertEquals(sentBefore, transport.sent, "An unadvertised methodId must not send a message")

        // The advertised method still works, so a rejected id is not a poisoned connection.
        client.login(AuthMethodId("oauth"))
        assertEquals(
            listOf("initialize", "auth/login"),
            transport.sent.filterIsInstance<JsonRpcRequest>().map { it.method.name },
        )
    }

    private suspend fun assertAuthenticationUnavailable(client: Client, transport: AuthTransport) {
        val sentBefore = transport.sent.toList()

        val loginFailure = assertFailsWith<AcpExpectedError> { client.login(AuthMethodId("oauth")) }
        assertTrue(loginFailure.message.contains("auth/login"))
        assertTrue(loginFailure.message.contains("authMethods"))
        assertEquals(sentBefore, transport.sent, "Unsupported login must not send a message")

        val logoutFailure = assertFailsWith<AcpExpectedError> { client.logout() }
        assertTrue(logoutFailure.message.contains("auth/logout"))
        assertTrue(logoutFailure.message.contains("authMethods"))
        assertEquals(sentBefore, transport.sent, "Unsupported logout must not send a message")
    }

    private fun withClient(
        initializeResponse: String,
        initialize: Boolean = true,
        block: suspend (Client, AuthTransport) -> Unit,
    ) = runBlocking {
        val transport = AuthTransport(ACPJson.parseToJsonElement(initializeResponse))
        val protocol = Protocol(this, transport)
        val client = Client(protocol)
        protocol.start()
        try {
            withTimeout(10.seconds) {
                if (initialize) {
                    client.initialize(ClientInfo(PROTOCOL_VERSION_V2, Implementation("client", "1")))
                }
                block(client, transport)
            }
        } finally {
            protocol.close()
        }
    }

    /** Replies using literal wire names and JSON so both SDK sides cannot hide a naming regression. */
    private class AuthTransport(private val initializeResponse: JsonElement) : BaseTransport() {
        val sent = mutableListOf<JsonRpcMessage>()

        override fun start() {
            _state.value = Transport.State.STARTED
        }

        override fun close() {
            _state.value = Transport.State.CLOSED
            fireClose()
        }

        override fun send(frame: TransportFrame) {
            val message = (frame as? TransportFrame.Single)?.message
                ?: throw IllegalArgumentException("Only TransportFrame.Single is supported")

            sent += message
            if (message !is JsonRpcRequest) return
            val response = when (message.method.name) {
                "initialize" -> JsonRpcSuccessResponse(message.id, result = initializeResponse)
                "auth/login", "auth/logout" -> JsonRpcSuccessResponse(
                    message.id,
                    result = ACPJson.parseToJsonElement("""{"_meta":{"source":"agent"}}"""),
                )
                else -> JsonRpcErrorResponse(
                    message.id,
                    error = JsonRpcError(JsonRpcErrorCode.METHOD_NOT_FOUND.code, "Unexpected method"),
                )
            }

            fireFrame(TransportFrame.Single(response))
        }
    }

    private companion object {
        const val AUTHENTICATED_AGENT = """{
            "protocolVersion":2,
            "info":{"name":"agent","version":"1"},
            "authMethods":[{"type":"agent","methodId":"oauth","name":"OAuth"}]
        }"""
    }
}

@file:OptIn(com.agentclientprotocol.annotations.UnstableApi::class)

package com.agentclientprotocol.model.v2

import com.agentclientprotocol.model.MessageId
import com.agentclientprotocol.model.SessionConfigId
import com.agentclientprotocol.model.SessionId
import com.agentclientprotocol.rpc.ACPJson
import kotlinx.serialization.KSerializer
import kotlinx.serialization.SerializationException
import kotlinx.serialization.json.jsonObject
import kotlin.test.Test
import kotlin.test.assertEquals
import kotlin.test.assertFailsWith
import kotlin.test.assertIs

class SessionSetupSerializationTest {
    private val modes = """"modes":{"currentModeId":"ask","availableModes":[]}"""

    private val options = listOf(
        SessionConfigOption(SessionConfigId("enabled"), "Enabled", kind = SessionConfigKind.Boolean(true)),
    )

    private val optionsJson =
        """"configOptions":[{"type":"boolean","configId":"enabled","name":"Enabled","currentValue":true}]"""

    @Test
    fun `new session request needs only cwd`() {
        assertEquals(
            NewSessionRequest("/work"),
            ACPJson.decodeFromString(NewSessionRequest.serializer(), """{"cwd":"/work"}"""),
        )
    }

    @Test
    fun `resume request needs only session id and cwd`() {
        assertEquals(
            ResumeSessionRequest(SessionId("s1"), "/work"),
            ACPJson.decodeFromString(ResumeSessionRequest.serializer(), """{"sessionId":"s1","cwd":"/work"}"""),
        )
    }

    @Test
    fun `empty additional directories are omitted from setup requests`() {
        assertEquals(
            """{"cwd":"/work","mcpServers":[]}""",
            ACPJson.encodeToString(NewSessionRequest.serializer(), NewSessionRequest("/work")),
        )
        assertEquals(
            """{"sessionId":"s1","cwd":"/work","mcpServers":[]}""",
            ACPJson.encodeToString(ResumeSessionRequest.serializer(), ResumeSessionRequest(SessionId("s1"), "/work")),
        )
        assertEquals(
            """{"sessionId":"s1","cwd":"/work","mcpServers":[]}""",
            ACPJson.encodeToString(ForkSessionRequest.serializer(), ForkSessionRequest(SessionId("s1"), "/work")),
        )
    }

    @Test
    fun `nonempty additional directories are encoded`() {
        assertEquals(
            """{"cwd":"/work","mcpServers":[],"additionalDirectories":["/lib"]}""",
            ACPJson.encodeToString(
                NewSessionRequest.serializer(),
                NewSessionRequest("/work", additionalDirectories = listOf("/lib")),
            ),
        )
        assertEquals(
            """{"sessionId":"s1","cwd":"/work","additionalDirectories":["/lib"],"mcpServers":[]}""",
            ACPJson.encodeToString(
                ResumeSessionRequest.serializer(),
                ResumeSessionRequest(SessionId("s1"), "/work", additionalDirectories = listOf("/lib")),
            ),
        )
    }

    @Test
    fun `resume request encodes replayFrom start`() {
        assertEquals(
            """{"sessionId":"s1","cwd":"/work","mcpServers":[],"replayFrom":{"type":"start"}}""",
            ACPJson.encodeToString(
                ResumeSessionRequest.serializer(),
                ResumeSessionRequest(SessionId("s1"), "/work", replayFrom = ReplayFrom.Start()),
            ),
        )
    }

    @Test
    fun `resume request without replayFrom omits the key`() {
        assertEquals(
            """{"sessionId":"s1","cwd":"/work","mcpServers":[]}""",
            ACPJson.encodeToString(ResumeSessionRequest.serializer(), ResumeSessionRequest(SessionId("s1"), "/work")),
        )
    }

    @Test
    fun `resume request reads absent and null replayFrom as no replay`() {
        val expected = ResumeSessionRequest(SessionId("s1"), "/work")
        assertEquals(
            expected,
            ACPJson.decodeFromString(ResumeSessionRequest.serializer(), """{"sessionId":"s1","cwd":"/work"}"""),
        )
        assertEquals(
            expected,
            ACPJson.decodeFromString(
                ResumeSessionRequest.serializer(),
                """{"sessionId":"s1","cwd":"/work","replayFrom":null}""",
            ),
        )
    }

    @Test
    fun `resume request decodes replayFrom start`() {
        assertEquals(
            ResumeSessionRequest(SessionId("s1"), "/work", replayFrom = ReplayFrom.Start()),
            ACPJson.decodeFromString(
                ResumeSessionRequest.serializer(),
                """{"sessionId":"s1","cwd":"/work","replayFrom":{"type":"start"}}""",
            ),
        )
    }

    @Test
    fun `resume request keeps an unknown cursor`() {
        val cursor = """{"type":"_from_message","messageId":"m1"}"""
        val json = """{"sessionId":"s1","cwd":"/work","mcpServers":[],"replayFrom":$cursor}"""

        val request = ACPJson.decodeFromString(ResumeSessionRequest.serializer(), json)

        val replayFrom = assertIs<ReplayFrom.Unknown>(request.replayFrom)
        assertEquals("_from_message", replayFrom.type)
        assertEquals(json, ACPJson.encodeToString(ResumeSessionRequest.serializer(), request))
    }

    @Test
    fun `setup responses carry config options and ignore v1 modes`() {
        assertEquals(
            NewSessionResponse(SessionId("s1"), options),
            ACPJson.decodeFromString(
                NewSessionResponse.serializer(),
                """{"sessionId":"s1",$modes,$optionsJson}""",
            ),
        )
        assertEquals(
            ResumeSessionResponse(options),
            ACPJson.decodeFromString(ResumeSessionResponse.serializer(), """{$modes,$optionsJson}"""),
        )
    }

    @Test
    fun `prompt response carries the inserted message id`() {
        val meta = ACPJson.parseToJsonElement("""{"trace":"prompt"}""")
        val response = PromptResponse(MessageId("user-1"), meta)
        val json = ACPJson.parseToJsonElement("""{"messageId":"user-1","_meta":{"trace":"prompt"}}""")

        assertEquals(json, ACPJson.encodeToJsonElement(PromptResponse.serializer(), response))
        assertEquals(response, ACPJson.decodeFromJsonElement(PromptResponse.serializer(), json))
    }

    @Test
    fun `prompt response requires a non-null message id`() {
        for (json in listOf("{}", """{"messageId":null}""")) {
            assertFailsWith<SerializationException>(json) {
                ACPJson.decodeFromString(PromptResponse.serializer(), json)
            }
        }
    }

    @Test
    fun `setup responses carry the initial commands`() {
        val commands = listOf(
            AvailableCommand("plan", "Make a plan", AvailableCommandInput.Text("what to plan")),
            AvailableCommand("review", "Review the change"),
        )
        val commandsJson = ACPJson.parseToJsonElement(
            """[{"name":"plan","description":"Make a plan","input":{"type":"text","hint":"what to plan"}},""" +
                """{"name":"review","description":"Review the change"}]"""
        )

        fun <T> assertCarriesCommands(serializer: KSerializer<T>, response: T) {
            val json = ACPJson.encodeToJsonElement(serializer, response)
            assertEquals(commandsJson, json.jsonObject["availableCommands"])
            assertEquals(response, ACPJson.decodeFromJsonElement(serializer, json))
        }

        val sessionId = SessionId("s")
        assertCarriesCommands(NewSessionResponse.serializer(), NewSessionResponse(sessionId, availableCommands = commands))
        assertCarriesCommands(ResumeSessionResponse.serializer(), ResumeSessionResponse(availableCommands = commands))
        assertCarriesCommands(ForkSessionResponse.serializer(), ForkSessionResponse(sessionId, availableCommands = commands))
    }

    @Test
    fun `setup responses decode a malformed command list leniently`() {
        val review = AvailableCommand("review", "Review the change")
        val cases = listOf<Pair<String, List<AvailableCommand>>>(
            """{"sessionId":"s","availableCommands":null}""" to emptyList(),
            """{"sessionId":"s","availableCommands":{"name":"review"}}""" to emptyList(),
            """{"sessionId":"s","availableCommands":"review"}""" to emptyList(),
            """{"sessionId":"s","availableCommands":[{"name":"broken"},""" +
                """{"name":"review","description":"Review the change"},42]}""" to listOf(review),
        )
        for ((json, expected) in cases) {
            assertEquals(expected, ACPJson.decodeFromString(NewSessionResponse.serializer(), json).availableCommands, json)
            assertEquals(expected, ACPJson.decodeFromString(ResumeSessionResponse.serializer(), json).availableCommands, json)
            assertEquals(expected, ACPJson.decodeFromString(ForkSessionResponse.serializer(), json).availableCommands, json)
        }
    }
}

package com.agentclientprotocol.model

import com.agentclientprotocol.annotations.UnstableApi
import com.agentclientprotocol.rpc.ACPJson
import kotlin.test.Test
import kotlin.test.assertEquals
import kotlin.test.assertNotNull
import kotlin.test.assertTrue

@OptIn(UnstableApi::class)
class AuthMethodSerializerTest {

    // Backward compatibility tests

    @Test
    fun `decodes AuthMethod without type field as AgentAuth for backward compatibility`() {
        val payload = """
            {
                "id": "auth-1",
                "name": "Default Auth",
                "description": "Agent-managed authentication"
            }
        """.trimIndent()

        val authMethod = ACPJson.decodeFromString(AuthMethod.serializer(), payload)

        assertTrue(authMethod is AuthMethod.AgentAuth)
        assertEquals("auth-1", authMethod.id.value)
        assertEquals("Default Auth", authMethod.name)
        assertEquals("Agent-managed authentication", authMethod.description)
    }

    @Test
    fun `decodes AuthMethod with type agent as AgentAuth`() {
        val payload = """
            {
                "id": "auth-2",
                "name": "Agent Auth",
                "type": "agent"
            }
        """.trimIndent()

        val authMethod = ACPJson.decodeFromString(AuthMethod.serializer(), payload)

        assertTrue(authMethod is AuthMethod.AgentAuth)
        assertEquals("auth-2", authMethod.id.value)
        assertEquals("Agent Auth", authMethod.name)
    }

    // EnvVarAuth tests

    @Test
    fun `decodes AuthMethod with type env_var as EnvVarAuth`() {
        val payload = """
            {
                "id": "auth-3",
                "name": "API Key",
                "description": "Set API key environment variable",
                "type": "env_var",
                "vars": [{"name": "API_KEY"}],
                "link": "https://example.com/get-key"
            }
        """.trimIndent()

        val authMethod = ACPJson.decodeFromString(AuthMethod.serializer(), payload)

        assertTrue(authMethod is AuthMethod.EnvVarAuth)
        assertEquals("auth-3", authMethod.id.value)
