            """{"optionId":"allow-once","name":"Allow once","kind":"allow_once"}]}"""
        val request = RequestPermissionRequest(SessionId("sess_1"), "Continue?", options)

        assertEquals(request, decode(json))
        assertEquals(json, encode(request))
        assertEquals(
